// Verifies Reachly's x-reachai-signature: t=<unix>,v1=<hex HMAC-SHA256 of "t.body">.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and REACHAI_WEBHOOK_SECRET in n8n's environment.
const crypto = require('crypto');
const secret = $env.REACHAI_WEBHOOK_SECRET;
const item = $input.first().json;
const header = item.headers['x-reachai-signature'] || '';
if (secret) {
  const parts = Object.fromEntries(header.split(',').map((part) => part.split('=')));
  const body = JSON.stringify(item.body);
  const expected = crypto.createHmac('sha256', secret).update(`${parts.t}.${body}`).digest('hex');
  const fresh = Math.abs(Date.now() / 1000 - Number(parts.t)) < 300;
  if (!fresh || !parts.v1 || !crypto.timingSafeEqual(Buffer.from(parts.v1), Buffer.from(expected))) {
    throw new Error('Invalid Reachly signature');
  }
}
const { workspace, owner, business, autopilot, links } = item.body;
return [{ json: {
  workspace: workspace?.name ?? '',
  plan: workspace?.plan ?? '',
  ownerName: owner?.name ?? '',
  ownerEmail: owner?.email ?? '',
  industry: business?.industry ?? '',
  city: business?.city ?? '',
  website: business?.website ?? '',
  offerings: (business?.offerings ?? []).map((o) => o.name).join(', '),
  automationsOn: (autopilot?.activeWorkflows ?? []).join(', '),
  firstSearch: links?.discovery ?? '',
  registeredAt: workspace?.createdAt ?? '',
} }];

